SET name = #{name}, teacher = #{teacher}, room = #{room}, day_of_week = #{dayOfWeek}, 
    time_slot = #{timeSlot}, color = #{color}, remind_enabled = #{remindEnabled}, 
    remind_minutes = #{remindMinutes}, start_week = #{startWeek}, end_week = #{endWeek}, 
    updated_at = #{updatedAt}
WHERE id = #{id}
